"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["40872"],{56475(e){e.exports=JSON.parse('{"id":"FIN-1499","slug":"look-ahead-bias","term":"Look-Ahead Bias","also_known_as":[],"difficulty":"Advanced","definition":"Look-ahead bias is an error in analysis or backtesting that occurs when information that would not have been available at the time is used to make decisions or predictions.","explanation":["When testing how a strategy would have performed historically, it is easy to accidentally use data that was only published later. This makes results look better than they could have been in reality.","Common causes include using company financial results as if they were known at the end of the quarter, when they were actually published weeks later; using economic data that were later revised, rather than the figures first released; and selecting companies based on information known only today, such as current index membership.","For example, a backtest that buys shares at the end of March based on first-quarter earnings would be using information not available until those earnings were reported in April or May, overstating the strategy\'s performance.","Look-ahead bias can make worthless strategies appear profitable. Avoiding it requires carefully tracking when information became available, using point-in-time databases that record data as it was originally published, and building in realistic delays. It is closely related to survivorship bias, which also distorts backtests."],"note":"","total":1500,"prev":{"slug":"long-term-investments","term":"Long-Term Investments"},"next":{"slug":"loss-aversion","term":"Loss Aversion"}}')}}]);